class Solution
{
public:
    int wordsTyping(vector<string>& sentence, int rows, int cols)
    {
        string cycle;
        for (const string& word : sentence) {
            cycle += word + " ";
        }
        long long pos = 0;
        int n = cycle.size();
        for (int r = 0; r < rows; ++r)
        {
            pos += cols;
            if (cycle[pos % n] == ' ')
            {
                ++pos;
            } else
            {
                while (pos > 0 && cycle[(pos - 1) % n] != ' ')
                {
                    --pos;
                }
            }
        }
        return pos / n;
    }
};
